import 'dart:convert';

import 'package:flutter/material.dart';

class QuestionableNavigationBar extends StatelessWidget {
  final int currentIndex;
  final ValueChanged<int> onSelect;

  const QuestionableNavigationBar({
    super.key,
    required this.currentIndex,
    required this.onSelect,
  });

  static const String _detourImage = '';
  static const String _crawlImage = '';
  static const String _nearbyImage = '';
  static const String _savedImage = '';
  static const String _helpImage = '';

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      top: false,
      child: Container(
        height: 108,
        decoration: const BoxDecoration(
          color: Color(0xFF111113),
          border: Border(
            top: BorderSide(color: Color(0xFF252527), width: 1),
          ),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Expanded(
              child: _ExactNavItem(
                label: 'DETOUR',
                imageData: _detourImage,
                selected: currentIndex == 0,
                onTap: () => _select(context, 0),
              ),
            ),
            Expanded(
              child: _ExactNavItem(
                label: 'CRAWL',
                imageData: _crawlImage,
                selected: currentIndex == 1,
                onTap: () => _select(context, 1),
              ),
            ),
            Expanded(
              flex: 2,
              child: _ExactNearbyItem(
                onTap: () => _select(context, 2),
              ),
            ),
            Expanded(
              child: _ExactNavItem(
                label: 'SAVED',
                imageData: _savedImage,
                selected: currentIndex == 3,
                onTap: () => _select(context, 3),
              ),
            ),
            Expanded(
              child: _ExactNavItem(
                label: 'HELP',
                imageData: _helpImage,
                selected: currentIndex == 4,
                onTap: () => _select(context, 4),
              ),
            ),
          ],
        ),
      ),
    );
  }

  void _select(BuildContext context, int index) {
    onSelect(index);
  }
}

class _ExactNavItem extends StatelessWidget {
  final String label;
  final String imageData;
  final bool selected;
  final VoidCallback onTap;

  const _ExactNavItem({
    required this.label,
    required this.imageData,
    required this.selected,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    return Semantics(
      button: true,
      selected: selected,
      label: label,
      child: InkWell(
        onTap: onTap,
        child: SizedBox(
          height: 102,
          child: Column(
            mainAxisAlignment: MainAxisAlignment.end,
            children: [
              SizedBox(
                height: 66,
                width: double.infinity,
                child: Image.memory(
                  base64Decode(imageData),
                  fit: BoxFit.contain,
                  filterQuality: FilterQuality.high,
                  gaplessPlayback: true,
                ),
              ),
              Text(
                label,
                style: TextStyle(
                  color: selected
                      ? const Color(0xFFD4AF37)
                      : const Color(0xFFF5F2E8),
                  fontSize: 10.5,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.9,
                ),
              ),
              const SizedBox(height: 2),
            ],
          ),
        ),
      ),
    );
  }
}

class _ExactNearbyItem extends StatelessWidget {
  final VoidCallback onTap;

  const _ExactNearbyItem({required this.onTap});

  @override
  Widget build(BuildContext context) {
    return Semantics(
      button: true,
      selected: true,
      label: 'NEARBY',
      child: InkWell(
        onTap: onTap,
        child: Transform.translate(
          offset: const Offset(0, -7),
          child: SizedBox(
            height: 108,
            child: Column(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                SizedBox(
                  height: 82,
                  width: 82,
                  child: ClipOval(
                    child: Image.memory(
                      base64Decode(QuestionableNavigationBar._nearbyImage),
                      fit: BoxFit.cover,
                      filterQuality: FilterQuality.high,
                      gaplessPlayback: true,
                    ),
                  ),
                ),
                const SizedBox(height: 1),
                const Text(
                  'NEARBY',
                  style: TextStyle(
                    color: Color(0xFFD4AF37),
                    fontSize: 10.5,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 0.9,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

